'use client';

import { useEffect, useRef, useState } from 'react';
import s from './site.module.css';

// Plays the high-resolution sprite atlases generated by the Clippy project.
// PixiJS and each atlas load lazily: nothing is fetched until the exhibit is
// near the viewport, and an animation is only fetched the first time it plays.

const BASE = '/rv/clippy/high';

const moods = [
  { id: 'waving', en: 'wave', de: 'winken' },
  { id: 'thinking', en: 'think', de: 'denken' },
  { id: 'reading', en: 'read', de: 'lesen' },
  { id: 'listening_music', en: 'music', de: 'musik' },
  { id: 'celebrating', en: 'celebrate', de: 'feiern' },
  { id: 'sleeping', en: 'sleep', de: 'schlafen' },
];

const says = {
  en: { neutral: '', waving: 'hey!', thinking: 'hmm…', reading: 'good chapter', listening_music: 'this one’s a tune', celebrating: 'shipped it!', sleeping: 'zzz', sleepy: 'need a minute…', excited: 'let’s go!', surprised: 'oh! hi', happy: 'hehe', dizzy: 'whoa, easy' },
  de: { neutral: '', waving: 'hey!', thinking: 'hmm…', reading: 'gutes Kapitel', listening_music: 'guter Song', celebrating: 'geschafft!', sleeping: 'zzz', sleepy: 'kurze Pause…', excited: 'los geht’s!', surprised: 'oh! hi', happy: 'hehe', dizzy: 'langsam, langsam' },
};

export default function ClippyStage({ language = 'en', hint, shakeHint, trigger, large = false, controls = true, interactive = true }) {
  const wrapRef = useRef(null);
  const hostRef = useRef(null);
  const apiRef = useRef(null);
  const triggerRef = useRef(trigger);
  triggerRef.current = trigger;
  const [state, setState] = useState('neutral');
  const [status, setStatus] = useState('idle'); // idle | loading | ready | failed

  useEffect(() => {
    const wrap = wrapRef.current;
    const host = hostRef.current;
    if (!wrap || !host) return undefined;
    let disposed = false;
    let app;
    let visible = false;
    let started = false;
    const cache = new Map();

    async function start() {
      if (started) return;
      started = true;
      setStatus('loading');
      try {
        const PIXI = await import('pixi.js');
        if (disposed) return;
        app = new PIXI.Application();
        await app.init({ width: 512, height: 512, backgroundAlpha: 0, antialias: true, resolution: Math.min(window.devicePixelRatio || 1, 2), autoDensity: true });
        if (disposed) { app.destroy(true); return; }
        app.canvas.className = s.clippyCanvas;
        host.appendChild(app.canvas);

        const sprite = new PIXI.Sprite();
        sprite.width = 512;
        sprite.height = 512;
        app.stage.addChild(sprite);

        const manifest = await fetch(`${BASE}/manifest.json`).then((r) => {
          if (!r.ok) throw new Error(`Clippy animation manifest request failed (${r.status}).`);
          return r.json();
        });
        const load = (id) => {
          if (!cache.has(id)) {
            const animation = manifest.animations[id];
            if (!animation) return Promise.reject(new Error(`Clippy animation '${id}' is missing from the high-resolution manifest.`));
            cache.set(id, Promise.all(animation.pages.map(async (page) => {
              const [texture, response] = await Promise.all([
                PIXI.Assets.load(`${BASE}/${page.image}`),
                fetch(`${BASE}/${page.atlas}`),
              ]);
              if (!response.ok) throw new Error(`Clippy atlas request failed (${response.status}): ${page.atlas}`);
              const atlas = await response.json();
              return Object.entries(atlas.frames).map(([key, entry]) => ({
                index: Number(key.match(/_(\d+)\.png$/)?.[1]),
                texture: new PIXI.Texture({ source: texture.source, frame: new PIXI.Rectangle(entry.frame.x, entry.frame.y, entry.frame.w, entry.frame.h) }),
              }));
            })).then((pages) => ({
              ...animation,
              frames: pages.flat().filter((frame) => Number.isFinite(frame.index)).sort((a, b) => a.index - b.index).map(({ texture }) => texture),
            })).then((loaded) => {
              if (loaded.frames.length !== loaded.frameCount) throw new Error(`Clippy animation '${id}' loaded ${loaded.frames.length} frames; expected ${loaded.frameCount}.`);
              return loaded;
            }));
          }
          return cache.get(id);
        };

        let animation = await load('neutral');
        let frames = animation.frames;
        if (disposed) return;
        let current = 'neutral';
        let index = 0;
        let acc = 0;
        let requested = 0;
        sprite.texture = frames[0];
        setStatus('ready');

        const play = async (id) => {
          const ticket = ++requested;
          setState(id);
          try {
            const next = await load(id);
            if (disposed || ticket !== requested) return;
            animation = next; frames = next.frames; current = id; index = 0; acc = 0;
            sprite.texture = frames[0];
          } catch {
            if (ticket === requested) setState('neutral');
          }
        };

        app.ticker.add((ticker) => {
          acc += (ticker.deltaMS * animation.fps) / 1000;
          while (acc >= 1) {
            acc -= 1;
            if (index < frames.length - 1) index += 1;
            else if (animation.playback === 'once') { play('neutral'); break; } else index = 0;
          }
          sprite.texture = frames[index];
        });
        if (!visible) app.ticker.stop();

        apiRef.current = { play, current: () => current };
        // The dedicated project page can ask the same player to demonstrate a scenario.
        if (triggerRef.current?.sequence) play(triggerRef.current.animation);
        else play('waving');
      } catch (error) {
        console.error('Clippy demo failed to start', error);
        if (!disposed) setStatus('failed');
      }
    }

    const observer = new IntersectionObserver(([entry]) => {
      visible = entry.isIntersecting;
      if (visible) start();
      if (app?.ticker) { if (visible) app.ticker.start(); else app.ticker.stop(); }
    }, { rootMargin: '200px 0px' });
    observer.observe(wrap);

    // Shake detection: several quick direction reversals over the mascot.
    let lastX = 0; let lastDir = 0; let flips = 0; let flipTimer = 0;
    const onMove = (event) => {
      if (event.pointerType === 'touch' || !apiRef.current) return;
      const dx = event.clientX - lastX;
      lastX = event.clientX;
      if (Math.abs(dx) < 6) return;
      const dir = Math.sign(dx);
      if (dir !== lastDir) {
        lastDir = dir; flips += 1;
        clearTimeout(flipTimer);
        flipTimer = setTimeout(() => { flips = 0; }, 500);
        if (flips >= 6 && apiRef.current.current() !== 'dizzy') { flips = 0; apiRef.current.play('dizzy'); }
      }
    };
    const onEnter = (event) => {
      if (event.pointerType === 'touch' || !apiRef.current) return;
      if (apiRef.current.current() === 'neutral') apiRef.current.play('thinking');
    };
    const onLeave = () => {
      if (apiRef.current?.current() === 'thinking') apiRef.current.play('neutral');
    };
    if (interactive) {
      host.addEventListener('pointermove', onMove);
      host.addEventListener('pointerenter', onEnter);
      host.addEventListener('pointerleave', onLeave);
    }

    return () => {
      disposed = true;
      observer.disconnect();
      clearTimeout(flipTimer);
      host.removeEventListener('pointermove', onMove);
      host.removeEventListener('pointerenter', onEnter);
      host.removeEventListener('pointerleave', onLeave);
      apiRef.current = null;
      if (app) { try { app.destroy(true, { children: true }); } catch { /* already gone */ } }
    };
  }, []);

  useEffect(() => {
    if (trigger?.sequence) apiRef.current?.play(trigger.animation);
  }, [trigger?.sequence]);

  const bubble = says[language][state];

  return (
    <div className={large ? s.clippyLarge : undefined} style={large ? { '--clippy-size': 'min(100%, 680px)' } : undefined} ref={wrapRef}>
      <div className={s.clippyPaper}>
        <button type="button" className={s.clippyHost} ref={hostRef} onClick={interactive ? () => apiRef.current?.play('happy') : undefined} aria-label="Clippy" tabIndex={interactive ? 0 : -1}>
          {status !== 'ready' && (
            // Static fallback until (or unless) the live sprite is running.
            <img className={s.clippyFallback} src="/rv/clippy-waving-high.webp" alt="" width="1254" height="1254" loading="lazy" decoding="async" />
          )}
        </button>
        <span className={s.clippySays} aria-live="polite" data-on={bubble ? 'true' : 'false'}>{bubble || ' '}</span>
      </div>
      {controls && (
        <>
          <div className={s.clippyMoods} role="group" aria-label={hint}>
            {moods.map((mood) => (
              <button key={mood.id} type="button" className={s.chip} data-active={state === mood.id} onClick={() => apiRef.current?.play(mood.id)} disabled={status !== 'ready'}>
                {mood[language]}
              </button>
            ))}
          </div>
          <p className={s.clippyHint}><span className={s.touchOnly}>{hint}</span><span className={s.hoverOnly}>{hint} · {shakeHint}</span></p>
        </>
      )}
    </div>
  );
}
